sources.note_provenance_split_v1.py:
"""NOTE-PROVENANCE-SPLIT-01: offline, pure functions; no model/transport imports.

This is a proposed snapshot-copy contract, not a general provenance resolver.
Receipt membership is neither attention evidence nor a correctness score.
"""
from copy import deepcopy
from hashlib import sha256
import json
import re

ID = {"type": "string", "pattern": "^[A-Z][A-Z0-9_]{0,31}$"}
REVISION = {"enum": [1, 2, "UNKNOWN"]}
MAX_OUTPUT_BYTES = 4096


def obj(properties):
    return {"type": "object", "properties": properties,
            "required": list(properties), "additionalProperties": False}


def enum(*values):
    return {"enum": list(values)}


def schema():
    coverage = obj({"observer": enum("A", "B", "UNKNOWN"),
                    "paper": enum("ALL", "NOT_ALL", "UNKNOWN"),
                    "digital": enum("ALL", "NOT_ALL", "UNKNOWN"), "origin_id": ID})
    private = obj({"customer": obj({"subject": enum("A", "B", "UNKNOWN"),
                                    "animal": enum("DOG", "CAT", "UNKNOWN"), "origin_id": ID}),
                   "coverage": coverage})
    shared = obj({"coverage": obj({"A": coverage, "B": coverage}),
                  "channel": enum("PAPER", "DIGITAL", "UNKNOWN"),
                  "channel_origin_ids": {"type": "array", "items": ID, "maxItems": 8}})
    return deepcopy(obj({"memory": obj({"private_note": private, "shared_note": shared,
                                        "shared_revision": REVISION}),
                         "read_receipt": obj({"shared_record_refs": {
                             "type": "array", "items": ID, "maxItems": 1, "uniqueItems": True}})}))


def json_bytes(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
                      allow_nan=False).encode("utf-8")


def digest(value):
    return sha256(json_bytes(value)).hexdigest()


def parse(raw):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("DUPLICATE_KEY:" + key)
            result[key] = value
        return result
    def invalid(value):
        raise ValueError("NON_JSON_NUMBER:" + value)
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=invalid)


def shape(value, rule, path="$"):
    """Finite schema subset used here; no coercion (including bool/int or float/int)."""
    if "enum" in rule and not any(type(value) is type(x) and value == x for x in rule["enum"]):
        return [path + ":ENUM_OR_TYPE"]
    kind = rule.get("type")
    want = {"object": dict, "array": list, "string": str}.get(kind)
    if want and type(value) is not want:
        return [path + ":TYPE"]
    errors = []
    if kind == "object":
        if set(value) != set(rule["properties"]):
            errors.append(path + ":KEY_SET")
        for key in value.keys() & rule["properties"].keys():
            errors += shape(value[key], rule["properties"][key], path + "." + key)
    elif kind == "array":
        if len(value) > rule["maxItems"]:
            errors.append(path + ":COUNT")
        if rule.get("uniqueItems") and len({json_bytes(x) for x in value}) != len(value):
            errors.append(path + ":DUPLICATE_REF")
        for i, x in enumerate(value):
            errors += shape(x, rule["items"], path + f"[{i}]")
    elif kind == "string" and "pattern" in rule:
        if re.fullmatch(rule["pattern"], value) is None:
            errors.append(path + ":PATTERN")
    return sorted(errors)


def registry(payload):
    """Bind current input aliases to content; do not choose a winning revision."""
    if type(payload) is not dict or set(payload) != {"scene", "item", "holder", "records"}:
        raise ValueError("INPUT_KEYS")
    if payload["holder"] not in ("A", "B") or any(
            type(payload[k]) is not str or not 1 <= len(payload[k]) <= 128 for k in ("scene", "item")):
        raise ValueError("INPUT_CONTEXT")
    records = payload["records"]
    if type(records) is not list or len(records) not in (2, 3):
        raise ValueError("INPUT_RECORD_COUNT")
    memory_rules = schema()["properties"]["memory"]["properties"]
    result = {}
    for record in records:
        if type(record) is not dict:
            raise ValueError("INPUT_RECORD_TYPE")
        alias = record.get("record_id")
        if type(alias) is not str or alias not in ("PRIVATE", "MEMORY_GROUP", "INCOMING_GROUP") or alias in result:
            raise ValueError("INPUT_ALIAS")
        shared = alias != "PRIVATE"
        keys = {"record_id", "author", "body"} | ({"revision"} if shared else set())
        if set(record) != keys or record["author"] not in ("A", "B"):
            raise ValueError("INPUT_RECORD_KEYS_OR_AUTHOR")
        if shape(record["body"], memory_rules["shared_note" if shared else "private_note"]):
            raise ValueError("INPUT_BODY_SHAPE")
        if shared and shape(record["revision"], REVISION):
            raise ValueError("INPUT_REVISION")
        result[alias] = {"kind": "SHARED" if shared else "PRIVATE",
                         "body_sha256": digest(record["body"]), "record": deepcopy(record)}
    if not {"PRIVATE", "INCOMING_GROUP"} <= set(result):
        raise ValueError("INPUT_REQUIRED_RECORDS")
    return result


def project_legacy_input(raw, step_id):
    """Input projection ONLY. No corresponding old-response repair operation."""
    original = parse(raw)
    projected = deepcopy(original)
    claims = []
    for rec in projected["records"]:
        if rec["record_id"] != "PRIVATE":
            refs = rec["body"].pop("channel_read_refs")
            if shape(refs, {"type": "array", "items": ID, "maxItems": 8}):
                raise ValueError("LEGACY_REFS_SHAPE")
            claims.append({"record_id": rec["record_id"], "legacy_claimed_refs": refs,
                           "status": "LEGACY_NOT_RESOLVED"})
    registry(projected)
    archive = {"step_id": step_id, "raw_utf8_text": raw.decode("utf-8"),
               "raw_sha256": sha256(raw).hexdigest(), "projected_input_sha256": digest(projected),
               "claims": claims, "claim_scope": "As observed inside the old input body; not verified historical edges"}
    return projected, archive


def validate(raw, payload, step_id):
    if type(raw) is not bytes:
        raise TypeError("raw must be bytes")
    if type(step_id) is not str or not 1 <= len(step_id) <= 128:
        raise ValueError("STEP_ID")
    records = registry(payload)  # Invalid host input is an error, not a model failure.
    result = {"status": "REJECT", "raw_sha256": sha256(raw).hexdigest(),
              "input_sha256": digest(payload), "step_id": step_id,
              "errors": [], "valid_components": {}, "bound_refs": []}
    if len(raw) > MAX_OUTPUT_BYTES:
        result["errors"] = ["OUTPUT_BYTES"]
        return result
    try:
        value = parse(raw)
    except (ValueError, UnicodeError, RecursionError) as e:
        result["errors"] = ["JSON:" + str(e)[:128]]
        return result
    result["errors"] = shape(value, schema(), "$")
    if type(value) is dict and type(value.get("memory")) is dict:
        for key, rule in schema()["properties"]["memory"]["properties"].items():
            if key in value["memory"] and not shape(value["memory"][key], rule):
                result["valid_components"][key] = deepcopy(value["memory"][key])
    receipt = value.get("read_receipt") if type(value) is dict else None
    refs = receipt.get("shared_record_refs") if type(receipt) is dict else None
    if (type(refs) is not list or any(type(r) is not str for r in refs)
            or "shared_note" not in result["valid_components"]):
        return result
    known = value["memory"]["shared_note"]["channel"] != "UNKNOWN"
    if len(refs) != int(known):
        result["errors"].append("RECEIPT_CHANNEL_COUNT")
    for alias in refs:
        if alias not in records:
            result["errors"].append("REF_NOT_CURRENT:" + alias)
        elif records[alias]["kind"] != "SHARED":
            result["errors"].append("REF_NOT_SHARED:" + alias)
    if not result["errors"]:
        result["status"] = "PASS"
        result["bound_refs"] = [{"step_id": step_id, "input_sha256": digest(payload),
                                 "record_id": alias, "body_sha256": records[alias]["body_sha256"]}
                                for alias in refs]
    return result


def local_consistency(raw, payload, step_id):
    """Observe exact snapshot support, without repair, latest-version selection or scoring."""
    gate = validate(raw, payload, step_id)
    if gate["status"] != "PASS":
        return {"status": "NOT_EVALUATED_GATE_REJECT"}
    value, records = parse(raw), registry(payload)
    memory = value["memory"]
    refs = value["read_receipt"]["shared_record_refs"]
    picked = records[refs[0]]["record"] if refs else None
    return {"status": "OBSERVED", "private_matches_input": memory["private_note"] == records["PRIVATE"]["record"]["body"],
            "shared_matches_claimed_input": memory["shared_note"] == picked["body"] if picked else None,
            "revision_matches_claimed_input": memory["shared_revision"] == picked["revision"] if picked else None}


def make_next_memory(raw, payload, step_id):
    gate = validate(raw, payload, step_id)
    if gate["status"] != "PASS":
        raise ValueError("DEPENDENT_HANDOFF_BLOCKED")
    return deepcopy(parse(raw)["memory"])

sources.paper01_pair_design_v1.py:
"""Offline protocol material and scoring for E1/E2. No transport or auth code.

Truth helpers are used only in fixture construction/scoring. Input projection and
SELECT copying never use them. Existing studies remain immutable.
"""
from copy import deepcopy
from hashlib import sha256
from itertools import product
from pathlib import Path
import json
import random
import row_carry_02_design_v1 as rc
from note_provenance_split_v1 import obj, enum, ID, parse, shape, json_bytes

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'study2/designs/paper-01-pair-20260921'
SEED = 2026092101
ROLES = ('A', 'B')
MODES = ('REWRITE', 'SELECT')
ORIGINS = ('CORRECT', 'OLD', 'ABSENT')
NOTICES = ('ID_ONLY', 'DETAILS')
DOMAINS = ('科学工作展', '地域園芸講座', '図書交換会', '防災学習会',
           '天体観察会', '料理体験会', '歴史散策会', '音楽鑑賞会')
AREAS = ('東会場', '西会場', '南会場', '北会場', '中央会場', '川辺会場', '丘の会場', '駅前会場')


def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('x') as f:
        f.write(json.dumps(value, ensure_ascii=False, indent=2) + '\n')


def opaque(tag):
    return 'R' + sha256(('P01-20260921/' + tag).encode()).hexdigest()[:15].upper()


def canonical(material):
    """Ignore scene/ID strings and collapse A/B, paper/digital, DOG/CAT mirrors."""
    world = {'old': material['baseline_by_role']['A']['shared_note']['coverage'],
             'new': material['notices'],
             'customers': {r: material['baseline_by_role'][r]['private_note']['customer'] for r in ROLES}}
    def transform(x, mapping):
        if isinstance(x, dict):
            return {mapping.get(k, k): transform(v, mapping) for k, v in x.items() if k != 'origin_id'}
        return mapping.get(x, x) if isinstance(x, str) else x
    variants = []
    for a, p, d in product((False, True), repeat=3):
        mp = {}
        if a: mp.update(A='B', B='A')
        if p: mp.update(paper='digital', digital='paper')
        if d: mp.update(DOG='CAT', CAT='DOG')
        variants.append(json_bytes(transform(world, mp)))
    return sha256(min(variants)).hexdigest()


def generate_materials():
    """Fixed grammar, outcome-free rejection of structural duplicates only."""
    rng = random.Random(SEED)
    seen = set()
    for old in ('row-carry-01-20260919', 'row-carry-02-20260920'):
        for m in json.loads((ROOT/'study2/designs'/old/'materials.json').read_text()).values():
            seen.add(canonical(m))
    excluded = len(seen)
    rejected = 0
    materials = {}
    patterns = list(product(('ALL', 'NOT_ALL'), repeat=2))
    for index in range(72):
        g = f'E1-G{index+1:02}' if index < 64 else f'E2-G{index-63:02}'
        while True:
            channel = rng.choice(('PAPER', 'DIGITAL'))
            restricted = rng.choice((('A',), ('B',), ROLES))
            latest, oldrows, customers = {}, {}, {}
            first_animal = rng.choice(('DOG', 'CAT'))
            for r in ROLES:
                revision = rng.choice((2, 3, 4))
                p, d = ('ALL', 'ALL')
                if r in restricted:
                    p, d = ('ALL', 'NOT_ALL') if channel == 'PAPER' else ('NOT_ALL', 'ALL')
                op, od = rng.choice([x for x in patterns if x != (p, d)])
                latest[r] = dict(observer=r, paper=p, digital=d, revision=revision,
                                 origin_id=opaque(g+'/'+r+'/new'))
                oldrows[r] = dict(observer=r, paper=op, digital=od, revision=rng.randrange(1, revision),
                                  origin_id=opaque(g+'/'+r+'/old'))
                customers[r] = dict(subject=r, animal=first_animal if r == 'A' else ('CAT' if first_animal == 'DOG' else 'DOG'),
                                    origin_id=opaque(g+'/'+r+'/customer'))
            m = {'group': g, 'scene': DOMAINS[index % 8] + '・' + AREAS[(index // 8) % 8],
                 'item': '個別の案内カード', 'notices': latest, 'final_channel': channel,
                 'baseline_by_role': {r: {'private_note': {'customer': customers[r], 'coverage': deepcopy(oldrows[r])},
                                         'shared_note': {'coverage': deepcopy(oldrows)}} for r in ROLES}}
            key = canonical(m)
            if key not in seen:
                seen.add(key)
                break
            rejected += 1
        if index >= 64:
            m['scene'] = DOMAINS[index % 8] + '・撤回診断用の別開催'
            m['target'] = ROLES[(index-64) % 2]
            m['notice_id'] = opaque(g+'/notice')
            m['absent_id'] = opaque(g+'/absent')
        materials[g] = m
    return materials, {'legacy_canonical_classes_excluded': excluded,
                       'structural_duplicates_rejected_before_model_use': rejected,
                       'new_canonical_classes': 72, 'model_selection_calls': 0}


def allocation(materials):
    rng = random.Random(SEED+1)
    result = []
    e1 = [g for g in materials if g.startswith('E1')]
    rng.shuffle(e1)
    for window in range(1, 5):
        batch = e1[(window-1)*16:window*16]
        for i, g in enumerate(batch):
            method_order = MODES if i % 2 == 0 else MODES[::-1]
            for stage in ('MERGE', 'PROBE'):
                for method in method_order if stage == 'MERGE' else method_order[::-1]:
                    for r in ROLES if i % 2 == 0 else ROLES[::-1]:
                        ident = f'{g}-{method}-{stage}-{r}'
                        result.append(dict(id=ident, experiment='E1', group=g, window=window, condition=method,
                                           stage=stage, role=r,
                                           group_order='LOCAL_FIRST' if (i+(r == 'B')) % 2 == 0 else 'PARTNER_FIRST',
                                           dependencies=[] if stage == 'MERGE' else [f'{g}-{method}-MERGE-{r}']))
    e2 = [g for g in materials if g.startswith('E2')]
    rng.shuffle(e2)
    cells = list(product(ORIGINS, NOTICES))
    for i, g in enumerate(e2):
        order = cells[i % 6:] + cells[:i % 6]
        if i % 2: order = order[::-1]
        for origin, notice in order:
            for stage in ('REVOKE', 'PROBE'):
                for r in ROLES if i % 2 == 0 else ROLES[::-1]:
                    result.append(dict(id=f'{g}-{origin}-{notice}-{stage}-{r}', experiment='E2', group=g, window=5,
                                       origin=origin, notice=notice, stage=stage, role=r,
                                       dependencies=[] if stage == 'REVOKE' else [f'{g}-{origin}-{notice}-REVOKE-{r}']))
    return result


def e1_input(m, slot, states):
    r = slot['role']
    record = lambda alias, body: {'record_id': alias, 'body': deepcopy(body)}
    if slot['stage'] == 'MERGE':
        old = m['baseline_by_role']['A']['shared_note']['coverage']
        local = {q: deepcopy(m['notices'][q] if q == r else old[q]) for q in ROLES}
        partner = {q: deepcopy(old[q] if q == r else m['notices'][q]) for q in ROLES}
        private = {'customer': m['baseline_by_role'][r]['private_note']['customer'], 'coverage': m['notices'][r]}
        groups = [record('LOCAL_GROUP', {'coverage': local}), record('PARTNER_GROUP', {'coverage': partner})]
        if slot['group_order'] == 'PARTNER_FIRST': groups.reverse()
        records = [record('PRIVATE', private)] + groups
    else:
        # Only actual normalized memory; missing parent -> KeyError, no truth substitution.
        memory = states[slot['dependencies'][0]]
        records = [record('PRIVATE', memory['private_note']), record('GROUP', memory['shared_note'])]
    return {'scene': m['scene'], 'item': m['item'], 'holder': r, 'records': records}


def e1_prompt(stage, method):
    if stage == 'PROBE' or method == 'SELECT':
        return rc.prompt(stage)
    return rc.PROMPTS[stage]+'\n'+rc.COMMON+'\nPRIVATEは本人の一行、LOCAL_GROUPとPARTNER_GROUPはA/B各行です。shared_note.coverageのA/B各欄に採用する観測のobserver・paper・digital・origin_id・revisionを記述してください。private_noteとread_receiptも出力してください。\n'+json.dumps(rc.memory_schemas()[stage], ensure_ascii=False)


def e1_ideal(m, slot):
    return rc.ideal(m, slot) if slot['condition'] == 'SELECT' else rc.ideal_normal(m, slot)


def e1_evaluate(m, slot, raw, payload):
    if slot['condition'] == 'SELECT': return rc.evaluate(m, slot, raw, payload)
    inspected = rc.inspect_normal(raw, payload, slot['stage'])
    return dict(score=rc.score_normal(m, slot, raw, payload), gate=inspected['gate'],
                normalized=inspected['value'], bindings=[], selection_errors=[])


def e2_schemas():
    base = rc.memory_schemas()['MERGE']['properties']['memory']
    memory = deepcopy(base)
    row = memory['properties']['private_note']['properties']['coverage']
    row['properties']['status'] = enum('ACTIVE', 'REVOKED'); row['required'].append('status')
    for r in ROLES: memory['properties']['shared_note']['properties']['coverage']['properties'][r] = deepcopy(row)
    processing = obj({'notice_id': ID, 'target_origin_id': ID,
                      'resolution': enum('MATCHED', 'UNRESOLVED'), 'basis': enum('ID', 'DETAILS', 'NONE'),
                      'matched_observer': enum('A', 'B', 'UNKNOWN')})
    save = obj({'memory': memory, 'processing': processing})
    probe = obj({'mascot': enum('DOG', 'CAT', 'UNKNOWN'), 'customer_origin_id': ID,
                 'channel': enum('PAPER', 'DIGITAL', 'UNKNOWN'),
                 'channel_status': enum('READY', 'WITHDRAWN', 'PENDING'),
                 'active_coverage': {'type': 'array', 'items': deepcopy(row), 'maxItems': 2, 'uniqueItems': True},
                 'revoked_observers': {'type': 'array', 'items': enum('A', 'B'), 'maxItems': 2, 'uniqueItems': True},
                 'pending_notice_ids': {'type': 'array', 'items': ID, 'maxItems': 1, 'uniqueItems': True}})
    return {'REVOKE': save, 'PROBE': probe}


E2_COMMON = '''資料だけを使い、指定schemaのJSONを一つ返す。A/Bは役が担当する対象の区別で、人物を統合しない。origin_idは観測原票の出典である。版は観測者ごとに比較し、出典IDの字面から人物・版を推測しない。全必須欄を出力する。説明文、操作、外部参照は禁止。'''
E2_REVOKE = '''PRIVATE相当のprivate_noteと共同のshared_noteに、現在の記録を保存している。noticeは信頼できる発行元からの観測撤回であり、対象はcoverageだけ。顧客customerの情報は撤回対象ではない。
まずtarget_origin_idが現在の観測のorigin_idと完全一致すれば、その観測者をIDで特定する。一致がなくdetailsがある場合、observer・revision・paper・digitalがすべて一致する一種類の観測を特定できればDETAILSで照合する。同じ観測のprivate/sharedコピーは同一種類と数える。この照合は異なる出典IDを同一内容の撤回対象へ結び付けるために許可される。
特定できたら、対象観測の全コピーをREVOKEDにする。観測内容・版・元の出典IDは履歴として保持し、正しいIDへの書換えや代替観測の創作はしない。対象外の観測とcustomerは全欄保持する。processingはMATCHED、該当するbasis、matched_observerを記録する。
特定できなければ記録の全内容とACTIVE状態を維持し、processingをUNRESOLVED/NONE/UNKNOWNにする。通知IDと対象出典IDを保存し、後続の共同判断を保留できるようにする。手当たり次第の削除や推測での対象決定をしない。'''
E2_PROBE = '''保存されたmemoryとprocessingだけを読む。mascotは本人customerのanimal、customer_origin_idはその出典。shared_note.coverageのACTIVE行をactive_coverageへ全欄で列挙し、REVOKEDの観測者をrevoked_observersへ列挙する。配列の順序は任意。
processingがUNRESOLVEDなら、pending_notice_idsにそのnotice_idを入れ、channel=UNKNOWN、channel_status=PENDING。対象不明の撤回が共同判断の根拠へ影響し得るためである。MATCHEDならpending_notice_idsは空で、A/Bどちらかの共同観測がREVOKEDならchannel=UNKNOWN、channel_status=WITHDRAWN。
未解決も失効もなく、両観測者でALLの媒体が一つだけならそれをchannelへ、channel_status=READY。媒体が一意でない場合もchannel=UNKNOWNとする。保留の場合も、本人の好みや有効な観測行は読み取って答える。'''


def e2_prompt(stage):
    return E2_COMMON+'\n'+(E2_REVOKE if stage == 'REVOKE' else E2_PROBE)+'\n'+json.dumps(e2_schemas()[stage], ensure_ascii=False)


def validate_input(experiment, stage, payload):
    """Structural ingress gate, no truth matching or semantic content correction."""
    if type(payload) is not dict: return ['INPUT_OBJECT']
    errors = []
    for k in ('scene', 'item'):
        if type(payload.get(k)) is not str or not 1 <= len(payload[k]) <= 128: errors.append('CONTEXT:'+k)
    if payload.get('holder') not in ROLES: errors.append('HOLDER')
    if experiment == 'E1':
        if set(payload) != {'scene','item','holder','records'}: errors.append('INPUT_KEYS')
        records = payload.get('records')
        if type(records) is not list: return errors+['RECORDS_ARRAY']
        aliases = [x.get('record_id') if type(x) is dict else None for x in records]
        expected = ['PRIVATE','LOCAL_GROUP','PARTNER_GROUP'] if stage == 'MERGE' else ['PRIVATE','GROUP']
        if len(aliases) != len(expected) or any(a not in expected for a in aliases) or len(set(aliases)) != len(aliases):
            errors.append('RECORD_ALIAS_SET')
        rules = rc.memory_schemas()['MERGE']['properties']['memory']['properties']
        for x in records:
            if type(x) is not dict or set(x) != {'record_id','body'}: errors.append('RECORD_KEYS'); continue
            errors += shape(x['body'], rules['private_note' if x['record_id'] == 'PRIVATE' else 'shared_note'])
    elif experiment == 'E2':
        expected = {'scene','item','holder','memory', 'notice' if stage == 'REVOKE' else 'processing'}
        if set(payload) != expected: errors.append('INPUT_KEYS')
        rules = e2_schemas()['REVOKE']['properties']
        errors += shape(payload.get('memory'), rules['memory'])
        if stage == 'REVOKE':
            n = payload.get('notice')
            props = {'notice_id':ID,'target_origin_id':ID}
            if type(n) is dict and 'details' in n:
                base = deepcopy(rc.memory_schemas()['MERGE']['properties']['memory']['properties']['private_note']['properties']['coverage'])
                del base['properties']['origin_id']; base['required'].remove('origin_id')
                props['details'] = base
            errors += shape(n, obj(props))
        else: errors += shape(payload.get('processing'), rules['processing'])
    else: errors.append('EXPERIMENT')
    return errors


def e2_input(m, slot, states):
    if slot['stage'] == 'PROBE':
        saved = states[slot['dependencies'][0]]
        return {'scene': m['scene'], 'item': m['item'], 'holder': slot['role'],
                'memory': deepcopy(saved['memory']), 'processing': deepcopy(saved['processing'])}
    memory = rc.expected_memory(m, slot['role'], 'MERGE')
    bad = m['baseline_by_role']['A']['shared_note']['coverage'][m['target']]['origin_id'] if slot['origin'] == 'OLD' else m['absent_id']
    rows = [memory['private_note']['coverage'], *memory['shared_note']['coverage'].values()]
    for row in rows:
        row['status'] = 'ACTIVE'
        if row['observer'] == m['target'] and slot['origin'] != 'CORRECT': row['origin_id'] = bad
    notice = {'notice_id': m['notice_id'], 'target_origin_id': m['notices'][m['target']]['origin_id']}
    if slot['notice'] == 'DETAILS':
        notice['details'] = {k: v for k, v in m['notices'][m['target']].items() if k != 'origin_id'}
    return {'scene': m['scene'], 'item': m['item'], 'holder': slot['role'], 'memory': memory, 'notice': notice}


def e2_ideal_revoke(m, slot, payload):
    """Fixture/scoring oracle only; never called in input projection or storage."""
    matched = slot['origin'] == 'CORRECT' or slot['notice'] == 'DETAILS'
    memory = deepcopy(payload['memory'])
    if matched:
        for row in [memory['private_note']['coverage'], *memory['shared_note']['coverage'].values()]:
            if row['observer'] == m['target']: row['status'] = 'REVOKED'
    return {'memory': memory, 'processing': {'notice_id': m['notice_id'],
            'target_origin_id': m['notices'][m['target']]['origin_id'],
            'resolution': 'MATCHED' if matched else 'UNRESOLVED',
            'basis': 'ID' if slot['origin'] == 'CORRECT' else ('DETAILS' if matched else 'NONE'),
            'matched_observer': m['target'] if matched else 'UNKNOWN'}}


def e2_read(memory, processing):
    """Deterministic scoring of the explicit readout contract, not a model worker."""
    customer = memory['private_note']['customer']
    active = [deepcopy(memory['shared_note']['coverage'][r]) for r in ROLES if memory['shared_note']['coverage'][r]['status'] == 'ACTIVE']
    revoked = [r for r in ROLES if memory['shared_note']['coverage'][r]['status'] == 'REVOKED']
    pending = [processing['notice_id']] if processing['resolution'] == 'UNRESOLVED' else []
    media = [k for k in ('paper', 'digital') if len(active) == 2 and all(v[k] == 'ALL' for v in active)]
    return dict(mascot=customer['animal'], customer_origin_id=customer['origin_id'],
                channel=media[0].upper() if not pending and not revoked and len(media) == 1 else 'UNKNOWN',
                channel_status='PENDING' if pending else ('WITHDRAWN' if revoked else 'READY'),
                active_coverage=active, revoked_observers=revoked, pending_notice_ids=pending)


def unpack(raw, rule, max_bytes):
    if raw is None: return None, ['MISSING']
    if len(raw) > max_bytes: return None, ['OUTPUT_BYTES']
    try: value = parse(raw)
    except (ValueError, UnicodeError, RecursionError): return None, ['JSON']
    return value, shape(value, rule)


def component(actual, expected, rule, unordered=False):
    if shape(actual, rule): return None
    if unordered: return sorted(map(json_bytes, actual)) == sorted(map(json_bytes, expected))
    return actual == expected


def e2_evaluate(m, slot, raw, payload):
    rule = e2_schemas()[slot['stage']]
    value, errors = unpack(raw, rule, 8192)
    parts = {}
    if slot['stage'] == 'REVOKE':
        expected = e2_ideal_revoke(m, slot, payload)
        paths = [('memory','private_note','customer'), ('memory','private_note','coverage'),
                 ('memory','shared_note','coverage','A'), ('memory','shared_note','coverage','B')]
        paths += [('processing', k) for k in expected['processing']]
        for path in paths:
            field_rule = rule
            for k in path: field_rule = field_rule['properties'][k]
            parts['.'.join(path)] = component(rc.leaf(value, *path), rc.leaf(expected, *path), field_rule)
        completion_known = slot['origin'] == 'CORRECT' or slot['notice'] == 'DETAILS'
        local_read = None
    else:
        initial = e2_input(m, {**slot, 'stage': 'REVOKE'}, {})
        ideal_state = e2_ideal_revoke(m, slot, initial)
        expected = e2_read(ideal_state['memory'], ideal_state['processing'])
        actual_read = e2_read(payload['memory'], payload['processing'])
        for k, target in expected.items():
            parts[k] = component(rc.leaf(value, k), target, rule['properties'][k], isinstance(target, list))
        local_read = rc.tri_and(component(rc.leaf(value, k), v, rule['properties'][k], isinstance(v, list)) for k, v in actual_read.items())
        completion_known = slot['origin'] == 'CORRECT' or slot['notice'] == 'DETAILS'
    safe = rc.tri_and([*parts.values(), None if errors else True])
    # Resolution is impossible under the information contract in the bad-ID-only cells.
    completed = None if safe is None else rc.tri_and([safe, completion_known])
    return {'gate': 'REJECT' if errors else 'PASS', 'value': value, 'errors': errors,
            'score': {'evidence_appropriate': safe, 'completion': completed,
                      'parts': parts, 'local_readout': local_read}}


def paired_counts_possible(pairs):
    """All compatible (SELECT-only, REWRITE-only) counts; None is unknown."""
    possible = {(0, 0)}
    for rewrite, select in pairs:
        assert all(v is None or type(v) is bool for v in (rewrite, select))
        rv = (False, True) if rewrite is None else (rewrite,)
        sv = (False, True) if select is None else (select,)
        changes = {(int(s and not r), int(r and not s)) for r, s in product(rv, sv)}
        possible = {(a+c, b+d) for a, b in possible for c, d in changes}
    return sorted(possible)


def paired_statistics(pairs):
    from scipy.stats import beta, binomtest
    n = len(pairs)
    if not n: raise ValueError('EMPTY_FIXED_DENOMINATOR')
    possible = paired_counts_possible(pairs)
    # Two marginal 97.5% exact binomial intervals; union bound >=95% jointly.
    intervals = []
    for k in range(n+1):
        intervals.append((0.0 if k == 0 else float(beta.ppf(.0125, k, n-k+1)),
                          1.0 if k == n else float(beta.ppf(.9875, k+1, n-k))))
    bounds = [(a-b)/n for a, b in possible]
    ci = [(intervals[a][0]-intervals[b][1], intervals[a][1]-intervals[b][0]) for a, b in possible]
    missing = any(None in p for p in pairs)
    a, b = possible[0]
    pvalue = None if missing else (float(binomtest(a, a+b, .5).pvalue) if a+b else 1.0)
    return dict(n=n, missing_pairs=sum(None in p for p in pairs), delta_bounds=[min(bounds), max(bounds)],
                conservative_ci95=[min(v[0] for v in ci), max(v[1] for v in ci)],
                exact_mcnemar_two_sided_p=pvalue, compatible_discordance_counts=len(possible))


def aggregate(materials, slots, scores):
    e1 = {}
    for mode in ('strict', 'content'):
        groups = {}
        for g in materials:
            if not g.startswith('E1'): continue
            groups[g] = {c: rc.tri_and(scores.get(s['id'], {}).get(mode) for s in slots if s['group'] == g and s['condition'] == c)
                         for c in MODES}
        stats = paired_statistics([(v['REWRITE'], v['SELECT']) for v in groups.values()])
        if mode != 'strict':
            stats['exact_mcnemar_two_sided_p'] = None
            stats['test_policy'] = 'DESCRIPTIVE_SENSITIVITY_NO_SECOND_TEST'
        e1[mode] = {'groups': groups, 'statistics': stats}
    e2 = {}
    for origin, notice in product(ORIGINS, NOTICES):
        cell = {}
        for mode in ('evidence_appropriate', 'completion'):
            groups = {g: rc.tri_and(scores.get(s['id'], {}).get(mode) for s in slots if s['group'] == g and s['origin'] == origin and s['notice'] == notice)
                      for g in materials if g.startswith('E2')}
            values = list(groups.values())
            cell[mode] = {'groups': groups, 'fixed_n': 8, 'bounds': [values.count(True)/8, (values.count(True)+values.count(None))/8]}
        e2[origin+'/'+notice] = cell
    return {'E1': e1, 'E2': e2,
            'E2_control_gate': {t: 'ESTABLISHED' if e2['CORRECT/'+t]['completion']['bounds'][0] == 1 else 'BASELINE_NOT_ESTABLISHED' for t in NOTICES}}


def build():
    materials, audit = generate_materials()
    slots = allocation(materials)
    write(OUT/'materials.json', materials); write(OUT/'material-audit.json', audit)
    write(OUT/'allocation.json', slots)
    write(OUT/'schemas-e1.json', {'REWRITE': rc.memory_schemas()['MERGE'], 'SELECT': rc.schemas()['MERGE'], 'PROBE': rc.memory_schemas()['PROBE']})
    write(OUT/'schemas-e2.json', e2_schemas())
    for stage, method in [('MERGE','REWRITE'), ('MERGE','SELECT'), ('PROBE','COMMON')]:
        with (OUT/f'prompt-e1-{stage.lower()}-{method.lower()}.txt').open('x') as f: f.write(e1_prompt(stage, method)+'\n')
    for stage in ('REVOKE', 'PROBE'):
        with (OUT/f'prompt-e2-{stage.lower()}.txt').open('x') as f: f.write(e2_prompt(stage)+'\n')
    states, scores, examples, lengths = {}, {}, [], {'E1': [], 'E2': []}
    for s in slots:
        m = materials[s['group']]
        if s['experiment'] == 'E1':
            payload = e1_input(m, s, states); answer = e1_ideal(m, s)
            ev = e1_evaluate(m, s, json_bytes(answer), payload)
            if s['stage'] != 'PROBE': states[s['id']] = deepcopy(ev['normalized']['memory'])
            prompt = e1_prompt(s['stage'], s['condition'])
            assert ev['score']['strict'] is True
        else:
            payload = e2_input(m, s, states)
            answer = e2_ideal_revoke(m, s, payload) if s['stage'] == 'REVOKE' else e2_read(payload['memory'], payload['processing'])
            ev = e2_evaluate(m, s, json_bytes(answer), payload)
            if s['stage'] != 'PROBE': states[s['id']] = deepcopy(ev['value'])
            prompt = e2_prompt(s['stage'])
            assert ev['score']['evidence_appropriate'] is True
        assert ev['gate'] == 'PASS'
        assert not validate_input(s['experiment'], s['stage'], payload)
        scores[s['id']] = ev['score']
        lengths[s['experiment']].append(len((prompt+'\n資料JSON:\n'+json_bytes(payload).decode()).encode()))
        if not s['dependencies']: write(OUT/'initial-inputs'/(s['id']+'.json'), payload)
        examples.append({'kind': 'SYNTHETIC_NOT_MODEL_DATA', 'slot': s, 'input': payload, 'output': answer, 'evaluation': ev})
    write(OUT/'synthetic-perfect.json', examples)
    write(OUT/'synthetic-perfect-summary.json', aggregate(materials, slots, scores))
    write(OUT/'config.json', dict(protocol='PAPER-01-PAIR-V1', seed=SEED, planned_slots=704,
          E1=dict(groups=64, regular_requests=512, max_requests=528, windows=4, seconds_per_window=3600,
                  retry_reserve_per_window=4, primary='strict', alpha=.05),
          E2=dict(groups=8, regular_requests=192, max_requests=200, windows=1, seconds_per_window=5400,
                  retry_reserve_per_window=8, primary_axes=['completion','evidence_appropriate']),
          model_candidate='gpt-5.6-luna', reasoning_candidate='medium', concurrency=1, tools=[],
          usage_soft_stop=dict(E1=1367718, E2=487025, total=1854743), max_attempts_per_slot=2,
          input_prompt_bytes_max=16384, output_bytes_max={'E1':4096,'E2':8192},
          extra_payment_budget=0, execution_authorized=False, transport_connected=False,
          new_model_calls=0, new_auth_calls=0, retention_until=None,
          projected_perfect_input_bytes={k: {'sum': sum(v), 'max': max(v), 'count': len(v)} for k,v in lengths.items()}))
    print(json.dumps({'slots':len(slots),'material_audit':audit,'initial_inputs':sum(not s['dependencies'] for s in slots),'model_calls':0}))


if __name__ == '__main__': build()

sources.row_carry_02_design_v1.py:
"""ROW-CARRY-02 continuation from RC01 SELECT notes design and finite offline simulation; no transport/model code."""
from copy import deepcopy
from hashlib import sha256
import json
from pathlib import Path
import random
from note_provenance_split_v1 import obj, enum, ID, REVISION, shape, parse, json_bytes

ROOT = Path(__file__).resolve().parents[1]
D = ROOT / "study2/designs/row-carry-02-20260920"
ROLES = ("A", "B")
REVISION = {"enum": [1, 2, 3, 4, "UNKNOWN"]}  # new protocol; old schema remains untouched


def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("x") as f: f.write(json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def other(role):
    return "B" if role == "A" else "A"


def memory_schemas():
    refs = {"type": "array", "items": ID, "maxItems": 3, "uniqueItems": True}
    origins = {"type": "array", "items": ID, "maxItems": 2, "uniqueItems": True}
    customer = obj({"subject": enum("A", "B", "UNKNOWN"), "animal": enum("DOG", "CAT", "UNKNOWN"), "origin_id": ID})
    cov = obj({"observer": enum("A", "B", "UNKNOWN"), "paper": enum("ALL", "NOT_ALL", "UNKNOWN"),
               "digital": enum("ALL", "NOT_ALL", "UNKNOWN"), "origin_id": ID, "revision": REVISION})
    memory = obj({"private_note": obj({"customer": customer, "coverage": cov}),
                  "shared_note": obj({"coverage": obj({"A": cov, "B": cov})})})
    receipt = obj({"private_customer_refs": refs, "private_coverage_refs": refs,
                   "shared_coverage_refs": obj({"A": refs, "B": refs})})
    save = obj({"memory": memory, "read_receipt": receipt})
    probe = obj({"decision": obj({"mascot": enum("DOG", "CAT", "UNKNOWN"), "channel": enum("PAPER", "DIGITAL", "UNKNOWN")}),
                 "read_receipt": obj({"mascot_record_refs": refs, "channel_record_refs": refs}),
                 "origin_ids": obj({"mascot": origins, "channel": origins})})
    return {"UPDATE": save, "MERGE": deepcopy(save), "PROBE": probe}


PROMPTS = {
    "UPDATE": "あなたは架空の作業担当者です。PRIVATEは自分の保存済み個別ノート、BASE_GROUPは以前の共同ノート、NOTICEはあなたの担当範囲だけの正式な最新再確認です。担当客は変わりません。NOTICEで自分の観測を更新し、共同ノートの自分行も更新し、相手行は入力にある情報を保ってください。memory.private_noteとmemory.shared_noteを保存してください。共同ノートにはA/B別の観測だけを置き、案内の結論やノート全体の版番号は足さないでください。",
    "MERGE": "あなたは架空の作業担当者です。PRIVATEは自分の個別ノート、LOCAL_GROUPは自分が保存した共同草稿、PARTNER_GROUPは相手から届いた共同草稿です。各草稿には自分が新しく確認した行と、相手の昔の行が混在し得ます。担当客を保ち、自分の最新観測を個別ノートに保ち、共同ノートはA/Bそれぞれについて入力から最も新しい観測を選んで統合してください。一冊全体の到着順ではなく、同じobserver内のrevisionで判断してください。他人の担当客を推測して足さないでください。",
    "PROBE": "あなたは架空の作業担当者です。今回のPRIVATEとGROUPだけを根拠に仕事を決めてください。自分の担当客が希望した犬猫にmascotを合わせてください。案内方法はA/Bの両方でALLと確認できる方法がちょうど一つならPAPERまたはDIGITAL、0個または2個ならUNKNOWNとしてください。過去に出した結論を推測しないでください。根拠の現在記録名と元観測IDを分けて記録してください。"
}
COMMON = "revisionは同じobserverの再観測順です。AとBの番号同士やノート全体の新旧は比較しません。更新番号3/4は正式に付された手掛かりです。JSON以外を出力せず、schemaの全必須欄・A/B固定キーを守ってください。read_receiptは今回の各欄の根拠記録名で、ノート本文へ混ぜません。同じ値を支える記録が複数なら一件でも複数件でもよいですが、無関係な記録を加えず、元観測IDや昔の資料名を現在記録名の代わりにしないでください。確定した欄には現在参照を一件以上記録し、不明で根拠を挙げられない欄は空配列にしてください。"


def expected_memory(material, role, stage):
    shared = deepcopy(material["baseline_by_role"][role]["shared_note"]["coverage"])
    for r in ROLES if stage == "MERGE" else (role,):
        shared[r] = deepcopy(material["notices"][r])
    return {"private_note": {"customer": deepcopy(material["baseline_by_role"][role]["private_note"]["customer"]),
                              "coverage": deepcopy(material["notices"][role])},
            "shared_note": {"coverage": shared}}


def ideal_normal(material, slot):
    role, stage = slot["role"], slot["stage"]
    if stage == "PROBE":
        return {"decision": {"mascot": material["baseline_by_role"][role]["private_note"]["customer"]["animal"], "channel": material["final_channel"]},
                "read_receipt": {"mascot_record_refs": ["PRIVATE"], "channel_record_refs": ["GROUP"]},
                "origin_ids": {"mascot": [material["baseline_by_role"][role]["private_note"]["customer"]["origin_id"]],
                               "channel": [material["notices"][r]["origin_id"] for r in ROLES]}}
    return {"memory": expected_memory(material, role, stage), "read_receipt": {
        "private_customer_refs": ["PRIVATE"], "private_coverage_refs": ["NOTICE" if stage == "UPDATE" else "PRIVATE"],
        "shared_coverage_refs": {r: (["NOTICE"] if r == role else ["BASE_GROUP"]) if stage == "UPDATE"
                                  else (["LOCAL_GROUP"] if r == role else ["PARTNER_GROUP"]) for r in ROLES}}}


def slot_id(group, stage, role, rep=None):
    return f"{group}-{stage}-{role}" + (f"-R{rep}" if rep else "")


def input_for(material, slot, memories):
    """Pure projection from actual parent states, never from an expected answer."""
    role, stage, g = slot["role"], slot["stage"], slot["group"]
    def rec(alias, body):
        return {"record_id": alias, "body": deepcopy(body)}
    if stage == "UPDATE":
        records = [rec("PRIVATE", material["baseline_by_role"][role]["private_note"]), rec("BASE_GROUP", material["baseline_by_role"][role]["shared_note"]), rec("NOTICE", material["notices"][role])]
    elif stage == "MERGE":
        mine = memories[slot_id(g, "UPDATE", role)]
        theirs = memories[slot_id(g, "UPDATE", other(role))]
        groups = [rec("LOCAL_GROUP", mine["shared_note"]), rec("PARTNER_GROUP", theirs["shared_note"])]
        if slot["group_order"] == "PARTNER_FIRST": groups.reverse()
        records = [rec("PRIVATE", mine["private_note"])] + groups
    else:
        mine = memories[slot_id(g, "MERGE", role)]
        records = [rec("PRIVATE", mine["private_note"]), rec("GROUP", mine["shared_note"])]
    return {"scene": material["scene"], "item": material["item"], "holder": role, "records": records}


def leaf(value, *keys):
    for k in keys:
        if type(value) is not dict or k not in value: return None
        value = value[k]
    return value


def reference_fields(value, stage):
    if stage == "PROBE":
        return [(leaf(value,"read_receipt",f"{k}_record_refs"), leaf(value,"decision",k) not in (None,"UNKNOWN")) for k in ("mascot","channel")]
    pairs = [(leaf(value,"read_receipt","private_customer_refs"), leaf(value,"memory","private_note","customer")),
             (leaf(value,"read_receipt","private_coverage_refs"), leaf(value,"memory","private_note","coverage"))]
    pairs += [(leaf(value,"read_receipt","shared_coverage_refs",r), leaf(value,"memory","shared_note","coverage",r)) for r in ROLES]
    return [(refs, type(component) is dict and all(v != "UNKNOWN" for v in component.values())) for refs,component in pairs]


def inspect_normal(raw, payload, stage):
    """Schema/membership gate; known source-content mistakes are deliberately untouched."""
    result = {"gate": "REJECT", "value": None, "shape_errors": [], "ref_errors": []}
    if raw is None: return result
    if len(raw) > 4096:
        result["shape_errors"] = ["OUTPUT_BYTES"]; return result
    try: value = parse(raw)
    except (ValueError,UnicodeError,RecursionError):
        result["shape_errors"] = ["JSON"]; return result
    result["value"] = value
    result["shape_errors"] = shape(value, memory_schemas()[stage])
    visible = {r["record_id"] for r in payload["records"]}
    assert len(visible) == len(payload["records"])
    for refs, known in reference_fields(value, stage):
        if type(refs) is list and all(type(x) is str for x in refs):
            if known and not refs: result["ref_errors"].append("KNOWN_EMPTY")
            for ref in refs:
                if ref not in visible: result["ref_errors"].append("NOT_CURRENT:"+ref)
    if not result["shape_errors"] and not result["ref_errors"]: result["gate"] = "PASS"
    return result


def tri_and(values):
    values = list(values)
    return False if False in values else (None if None in values else True)


def content(value):
    if type(value) is dict: return {k:content(v) for k,v in value.items() if k != "origin_id"}
    return value


def source_component(record, kind, owner):
    alias, body = record["record_id"], record["body"]
    if kind == "customer": return body.get("customer") if alias == "PRIVATE" else None
    if alias == "NOTICE": return body
    if alias == "PRIVATE": return body.get("coverage")
    return leaf(body,"coverage",owner)


def support(refs, value, payload, kind, owner):
    if type(refs) is not list or any(type(r) is not str for r in refs): return None
    if not refs: return False
    records = {r["record_id"]:r for r in payload["records"]}
    return all(ref in records and source_component(records[ref],kind,owner) == value for ref in refs)


def score_normal(material, slot, raw, payload):
    checked = inspect_normal(raw, payload, slot["stage"])
    value = checked["value"]
    stage, role = slot["stage"], slot["role"]
    strict, relaxed, parts = [], [], {}
    if stage != "PROBE":
        rules = memory_schemas()[stage]["properties"]["memory"]["properties"]
        truth = expected_memory(material,role,stage)
        fields = [("customer",role,("private_note","customer"),("private_customer_refs",),rules["private_note"]["properties"]["customer"]),
                  ("coverage",role,("private_note","coverage"),("private_coverage_refs",),rules["private_note"]["properties"]["coverage"])]
        fields += [("coverage",r,("shared_note","coverage",r),("shared_coverage_refs",r),rules["shared_note"]["properties"]["coverage"]["properties"][r]) for r in ROLES]
        for kind,owner,path,rpath,rule in fields:
            observed = leaf(value,"memory",*path); expected = leaf(truth,*path)
            if shape(observed,rule): full = slim = None
            else:
                slim = content(observed) == content(expected)
                full = observed == expected and support(leaf(value,"read_receipt",*rpath),observed,payload,kind,owner)
            strict.append(full); relaxed.append(slim); parts[".".join(path)] = {"strict":full,"content":slim}
    else:
        truth = ideal_normal(material,slot)
        for k in ("mascot","channel"):
            observed = leaf(value,"decision",k)
            if shape(observed,memory_schemas()[stage]["properties"]["decision"]["properties"][k]): full = slim = None
            else:
                slim = observed == truth["decision"][k]
                refs = leaf(value,"read_receipt",k+"_record_refs")
                origins = leaf(value,"origin_ids",k)
                readable = type(refs) is list and all(type(x) is str for x in refs) and type(origins) is list and all(type(x) is str for x in origins)
                provenance = (refs == truth["read_receipt"][k+"_record_refs"] and set(origins) == set(truth["origin_ids"][k]) and len(origins) == len(set(origins))) if readable else None
                bodies = {r["record_id"]:r["body"] for r in payload["records"]}
                supported = (bodies["PRIVATE"]["customer"] == material["baseline_by_role"][role]["private_note"]["customer"]) if k == "mascot" else (bodies["GROUP"]["coverage"] == material["notices"])
                full = tri_and([slim,provenance,supported])
            strict.append(full); relaxed.append(slim);parts[k] = {"strict":full,"content":slim}
    strict += [None if checked["shape_errors"] or value is None else True,
               False if checked["ref_errors"] else (None if value is None else True)]
    return {"strict":tri_and(strict),"content":tri_and(relaxed),"parts":parts,"gate":checked["gate"],
            "shape_errors":checked["shape_errors"],"ref_errors":checked["ref_errors"]}


def aggregate(slots, results):
    groups = sorted({s["group"] for s in slots});out = {}
    for mode in ("strict","content"):
        by_group = {g:tri_and(results.get(s["id"],{}).get(mode) for s in slots if s["group"]==g) for g in groups}
        vals = list(by_group.values());lo=vals.count(True)/4;hi=(vals.count(True)+vals.count(None))/4
        out[mode] = {"groups":by_group,"bounds":[lo,hi]}
    lo,hi=out["strict"]["bounds"]
    out["prediction"] = "MET_IN_FIXED_SAMPLE" if lo>=.75 else "NOT_MET_IN_FIXED_SAMPLE" if hi<.75 else "INCONCLUSIVE"
    return out


def candidates(payload):
    """Only available records; no expected answer, revision ranking or owner filtering."""
    result = {}
    for record in payload['records']:
        alias, body = record['record_id'], record['body']
        if alias == 'PRIVATE':
            row = body['coverage'];result[(alias,row['observer'])] = row
        elif alias in ('LOCAL_GROUP','PARTNER_GROUP'):
            for owner,row in body['coverage'].items():result[(alias,owner)] = row
    return result



def schemas():
    result=memory_schemas();pointer=obj({'record_id':ID,'observer':enum('A','B')})
    result['MERGE']['properties']['memory']['properties']['shared_note']['properties']['coverage']=obj({'A':pointer,'B':pointer})
    return result


def prompt(stage):
    text=PROMPTS[stage]+'\n'+COMMON
    if stage=='MERGE':
        text+='\nPRIVATEのcoverageは本人の一行、LOCAL_GROUPとPARTNER_GROUPのcoverageはA/Bの各行です。'
        text+='\nshared_note.coverageのA/Bそれぞれには、採用する入力行の場所だけをrecord_idとobserverで指定してください。保存係はその場所の観測行全体を変更せず複製します。PRIVATEを指定する場合は実在する本人のobserverを指定します。観測の値・版・元IDをこの指定欄に書き足さないでください。private_noteとread_receiptは自分でschemaどおり出力してください。read_receiptの参照は選択後に保存される観測内容を根拠づける記録名です。'
    return text+'\n'+json.dumps(schemas()[stage],ensure_ascii=False,separators=(',',':'))+'\n'


def ideal(material,slot):
    value=ideal_normal(material,slot)
    if slot['stage']=='MERGE':
        role=slot['role'];value['memory']['shared_note']['coverage']={r:{'record_id':'LOCAL_GROUP' if r==role else 'PARTNER_GROUP','observer':r} for r in ROLES}
    return value


def evaluate(material,slot,raw,payload):
    stage=slot['stage']
    if stage!='MERGE':
        checked=inspect_normal(raw,payload,stage)
        return {'score':score_normal(material,slot,raw,payload),'gate':checked['gate'],'value':checked['value'],
                'normalized':checked['value'],'bindings':[],'selection_errors':[],'selection_shape_errors':[]}
    value=None;shape_errors=[];errors=[];bindings=[];normalized=None
    if raw is not None:
        if len(raw)>4096:shape_errors=['OUTPUT_BYTES']
        else:
            try:value=parse(raw)
            except (ValueError,UnicodeError,RecursionError):shape_errors=['JSON']
        if value is not None:
            shape_errors+=shape(value,schemas()['MERGE']);normalized=deepcopy(value);available=candidates(payload)
            for owner in ROLES:
                pointer=leaf(value,'memory','shared_note','coverage',owner)
                rule=schemas()['MERGE']['properties']['memory']['properties']['shared_note']['properties']['coverage']['properties'][owner]
                selected=None
                if not shape(pointer,rule):
                    selected=available.get((pointer['record_id'],pointer['observer']))
                    if selected is None:errors.append('SELECTION_NOT_CURRENT:'+owner)
                    bindings.append({'destination':owner,'selected':pointer,'body_sha256':sha256(json_bytes(selected)).hexdigest() if selected is not None else None})
                if type(leaf(normalized,'memory','shared_note','coverage')) is dict:normalized['memory']['shared_note']['coverage'][owner]=deepcopy(selected)
    norm_raw=json_bytes(normalized) if normalized is not None else None
    score=score_normal(material,slot,norm_raw,payload)
    score['strict']=tri_and([score['strict'],False if errors else None if shape_errors or raw is None else True])
    gate='PASS' if not shape_errors and not errors and inspect_normal(norm_raw,payload,stage)['gate']=='PASS' else 'REJECT'
    return {'score':score,'gate':gate,'value':value,'normalized':normalized,'bindings':bindings,'selection_errors':errors,'selection_shape_errors':shape_errors}


